// ---------- RESIDENT APP (Rohan Sharma · Sunrise Boys PG · A-201 Bed B) ----------
const RH='Home',RR='Rent & payments',RC='Complaints',RN='Notices',RP='Profile';
const myN=()=>DB.notices.filter(n=>(n.propId==='p1'||n.propId==='all')&&n.state==='Sent');
const myC=()=>DB.comp.filter(c=>c.resId===DB.me);
const myInv=()=>resInv(DB.me);

def('rHome',{t:'Resident home',m:RH,r:'res',tab:'rHome',code:'H-01',d:'What a resident needs daily: their PG and exact bed, the next rent amount and date with a Pay button, today’s menu, latest notices and reminders. No owner functions exist anywhere in this app.',try:['Tap “Pay now”.','Tap the room card for room details.','Tap a notice.'],
 v:()=>{const me=ME(),i=myInv(),b=BD(me.bedId),R=RM(b.roomId),B=BL(R.bldId),P=PR(me.propId),paid=i.status==='Paid',un=myN().filter(n=>!n.read);
 return page({bar:`<div class="ab"><div style="flex:1"><div class="t-s mut">Good afternoon</div><h1>Rohan</h1></div><button class="ib" data-tab="rNotices" aria-label="Notices">${ic('bell')}${un.length?'<span class="dot"></span>':''}</button></div>`,body:`
 ${card(`<div class="between">${lbl(paid?'December rent':'Rent due')}${paid?sb('Paid'):bdg('Due '+i.due,'info')}</div><div class="t-xxl w7 num" style="margin:6px 0 2px">${inr(paid?i.total:i.total-i.paid)}</div><div class="t-s" style="color:#B9C6E4">${paid?'Paid · thank you! Receipt is in Rent.':'Rent '+inr(i.items[0].a)+' + electricity '+inr(i.items[1].a)+' · '+i.month}</div><div style="margin-top:12px">${paid?btn('View receipt',{k:'s',go:'rReceipt',p:{id:DB.pay.filter(x=>x.resId===DB.me).slice(-1)[0]?.id}}):btn('Pay now',{k:'s',icon:'rupee',go:'rPayMethod',style:'color:var(--navy)'})}</div>`,'',{style:'background:var(--navy);color:#fff;border-color:var(--navy)'})}
 ${card(`<div class="row">${propTile(P,44)}<div style="flex:1"><div class="w7">${P.name}</div><div class="t-s mut">${P.addr}, ${P.city}</div></div>${ic('right','sm mut2')}</div><div class="g4" style="margin-top:12px;text-align:center">${[['Building',B.code==='A'?'Block A':B.name],['Floor',R.floor],['Room',R.no],['Bed',b.label]].map(([l,v])=>`<div style="background:var(--slate-50);border-radius:10px;padding:8px 2px"><div class="w7">${v}</div><div class="t-xs mut">${l}</div></div>`).join('')}</div>`,'',{go:'rRoom'})}
 <div class="qa">${[['wrench','Raise complaint','rCompNew','var(--red-50)','var(--red)'],['file','PG rules','rRules','var(--blue-50)','var(--blue)'],['door','Visitors','rVisitors','var(--violet-50)','var(--violet)']].map(([ic_,l,g,bg,fg])=>`<div data-go="${g}" role="button" tabindex="0"><span class="tile" style="background:${bg};color:${fg}">${ic(ic_)}</span>${l}</div>`).join('')}</div>
 ${card(`<div class="between"><b>Today’s menu</b><span class="t-s mut">Tue</span></div><div class="t-s" style="display:grid;gap:5px;margin-top:8px">${['Breakfast','Lunch','Dinner'].map((m,k)=>`<div class="row" style="gap:8px">${ic('food','sm c-warn')}<span class="mut" style="width:64px">${m}</span><span>${MENU.Tue[k]}</span></div>`).join('')}</div>`)}
 ${sec('Notices',`View all`,{tab:'rNotices'})}${list(myN().slice(0,2).map(n=>li({icon:n.type==='Maintenance'?'wrench':n.type==='Important'?'alert':'mega',bg:n.type==='Important'?'var(--red-50)':'var(--blue-50)',fg:n.type==='Important'?'var(--red)':'var(--blue)',title:(n.read?'':'● ')+n.title,sub:n.date,go:'rNoticeDetail',p:{id:n.id}})))}
 ${sec('Reminders')}${list([li({icon:'shield',bg:'var(--green-50)',fg:'var(--green)',title:'KYC verified',sub:'Aadhaar via DigiLocker',chev:false}),li({icon:'drop',bg:'var(--amber-50)',fg:'var(--amber)',title:'Water off Thu, 10 AM–2 PM',sub:'Store water in advance',go:'rNoticeDetail',p:{id:'N1'}})])}
 ${sec('Recent activity')}${list([...myC().slice(0,1).map(c=>li({icon:'wrench',title:c.title,sub:'Complaint · '+c.status,go:'rCompDetail',p:{id:c.id}})),li({icon:'receipt',title:'Paid ₹8,390 for Nov 2026',sub:'3 Nov · UPI',go:'rHistory'})])}`})}});

def('rRoom',{t:'My PG, room & bed',m:RH,r:'res',tab:'rHome',code:'H-02',d:'The resident’s allocation in full: PG, building, floor, room, bed, rent, check-in date, amenities, who manages the PG and how to reach them. Roommates show first names only for privacy.',
 v:()=>{const me=ME(),b=BD(me.bedId),R=RM(b.roomId),B=BL(R.bldId),P=PR(me.propId),mates=DB.beds.filter(x=>x.roomId===R.id);
 return page({title:'My room',sub:P.name,body:`${illus(P,110,`<span class="bdg" style="background:#fff;color:var(--ink)">${ic('pin','sm')}${P.area}</span>${sb(me.status)}`)}
 ${card(kv([['PG',P.name],['Address',`${P.addr}, ${P.city} ${P.pin}`],['Building',B.name],['Floor','Floor '+R.floor],['Room',R.no+' · '+R.type],['Bed','Bed '+b.label],['Monthly rent',inr(me.rent)],['Checked in',me.join],['Status',me.status]]))}
 ${sec('Your room')}<div class="bedgrid">${mates.map(x=>{const r=resOnBed(x.id);const mine=x.id===b.id;return `<div class="bed ${mine?'Reserved':x.status==='Occupied'?'Occupied':'Available'}" style="cursor:default">${ic('bed')}<span>Bed ${x.label}</span><span class="t-xs">${mine?'You':r?r.first:'Vacant'}</span></div>`}).join('')}</div>
 ${sec('Amenities')}<div class="chips">${P.amen.map(a=>bdg(a,'mute')).join('')}</div>
 ${sec('Wi-Fi')}${card(kv([['Network','Sunrise_5G'],['Password','Shown at front desk']]))}
 ${sec('PG contacts')}${list([li({av:'RP',title:'Ramesh Parmar',sub:'Manager · 9 AM–7 PM',right:btn('Call',{k:'s',sm:true,act:'toast',p:{m:'Calling +91 98240 11223'}}),chev:false}),li({av:'MS',title:'Mahesh Solanki',sub:'Night warden · 8 PM–8 AM',right:btn('Call',{k:'s',sm:true,act:'toast',p:{m:'Calling +91 97245 63018'}}),chev:false}),li({av:'DP',title:'Deven Patel',sub:'Owner',right:btn('WhatsApp',{k:'wa',sm:true,act:'toast',p:{m:'Opening WhatsApp'}}),chev:false})])}`})}});

// ---------- RENT ----------
def('rRent',{t:'Rent',m:RR,r:'res',tab:'rRent',code:'Y-01',d:'Rent dashboard: current invoice with Pay, pending dues, this month’s electricity share and payment history with receipts.',try:['Tap “Pay ₹8,420”.','Open the History tab and tap a receipt.'],
 empty:{icon:'receipt',title:'No invoices yet',msg:'Your first rent invoice will appear here after check-in.'},
 v:()=>{const i=myInv(),t=U('rrt','cur'),paid=i.status==='Paid',R=RM(BD(ME().bedId).roomId);
 return page({body:`${seg('rrt',[['cur','Current'],['hist','History']],'cur')}
 ${t==='cur'?`${card(`<div class="between">${lbl(i.month+' invoice')}${sb(i.status)}</div><div class="t-xxl w7 num" style="margin:6px 0 2px">${inr(paid?i.total:i.total-i.paid)}</div><div class="t-s mut">${paid?'Paid in full':'Due on '+i.due+' · ₹500 late fee after 10 Dec'}</div>`,'',{go:'rInvoice'})}
 ${paid?banner('ok','check','Payment complete. Thank you!'):banner('info','clock',`Payment pending. ${inr(i.total-i.paid)} due on ${i.due.replace(' 2026','')}.`)}
 ${sec('Breakdown','Details',{go:'rInvoice'})}${card(kv(i.items.map(x=>[x.n,inr(x.a)])))}
 ${sec('Electricity · November')}${card(kv([['Room meter',`${R.meterPrev} → ${R.meterCur} (${R.meterCur-R.meterPrev} units)`],['Rate','₹9 / unit'],['Split between',DB.beds.filter(b=>b.roomId===R.id&&b.status==='Occupied').length+' occupied beds'],['Your share',inr((R.meterCur-R.meterPrev)*9/Math.max(1,DB.beds.filter(b=>b.roomId===R.id&&b.status==='Occupied').length))]]))}
 ${sec('Pending dues')}${card(paid?'<div class="t-s mut">No pending dues.</div>':kv([[i.month+' rent',inr(i.total-i.paid)],['Older dues','₹0']]))}`:''}
 ${t==='hist'?`${card(`<div class="between"><div>${lbl('Paid in 2026')}<div class="t-l w7 num">${inr(sum(DB.hist,h=>h.total)+(paid?i.total:0))}</div></div>${btn('Statement',{k:'s',sm:true,icon:'download',act:'toast',p:{m:'2026 rent statement PDF downloaded'}})}</div>`)}${list([...DB.pay.filter(x=>x.resId===DB.me).reverse().map(x=>li({icon:'receipt',bg:'var(--green-50)',fg:'var(--green)',title:'Dec 2026 · '+inr(x.amt),sub:`Paid ${x.date} · ${x.method}`,right:sb('Paid'),go:'rReceipt',p:{id:x.id}})),...DB.hist.map(h=>li({icon:'receipt',bg:'var(--green-50)',fg:'var(--green)',title:`${h.month} · ${inr(h.total)}`,sub:`Paid ${h.paidOn} · ${h.method}`,right:sb('Paid'),go:'rReceipt',p:{h:h.id}}))])}`:''}`,foot:!paid&&t==='cur'?btn(`Pay ${inr(i.total-i.paid)}`,{icon:'rupee',go:'rPayMethod'}):''})}});

def('rInvoice',{t:'Invoice details',m:RR,r:'res',tab:'rRent',code:'Y-02',d:'The invoice as the resident sees it: each line item, due date, late fee rule and total.',
 v:()=>{const i=myInv();return page({title:i.id,sub:i.month,right:`<button class="ib" data-act="toast" data-p="m:Invoice PDF downloaded" aria-label="Download">${ic('download')}</button>`,body:`<div class="doc"><div class="between"><div class="row">${propTile(PR('p1'),34)}<div><div class="w7">Sunrise Boys PG</div><div class="t-xs mut">Deven PG Group</div></div></div>${sb(i.status)}</div><div class="hr"></div>${kv([['Invoice no.',i.id],['Issued',i.issued],['Due date',i.due],['Billed to','Rohan Sharma · A-201 Bed B']])}<div class="hr"></div>${kv(i.items.map(x=>[x.n,inr(x.a)]))}<div class="hr"></div>${kv([['Total',`<span class="t-l">${inr(i.total)}</span>`],['Paid',inr(i.paid)],['Balance',inr(i.total-i.paid)]])}<div class="t-xs mut">Late fee of ₹500 applies if unpaid 5 days after the due date.</div></div>
 ${btn('Question about this bill?',{k:'g',go:'rCompNew',p:{cat:'Other'}})}`,foot:i.status!=='Paid'?btn('Pay now',{icon:'rupee',go:'rPayMethod'}):''})}});

def('rPayMethod',{t:'Choose payment method',m:RR,r:'res',tab:'rRent',code:'Y-03',d:'Pay through the gateway (UPI apps, UPI ID, card, net banking) — confirmed instantly. Cash is not paid in the app; the manager records it and the receipt appears automatically.',try:['Pick Google Pay and continue.'],
 v:()=>{const i=myInv(),m=F('rpm','gpay');const opt=(k,icon,t,s)=>li({lead:`<div class="tile" style="background:var(--slate-50);color:var(--ink)">${icon}</div>`,title:t,sub:s,right:`<span class="radio ${m===k?'on':''}"></span>`,act:'pick',p:{id:'rpm',v:k},chev:false});
 return page({title:'Pay rent',body:`${card(`<div class="between"><div>${lbl('Amount')}<div class="t-xl w7 num">${inr(i.total-i.paid)}</div></div><div class="t-s mut" style="text-align:right">${i.month}<br>Sunrise Boys PG</div></div>`)}
 ${pick('rpa',[['full','Full amount'],['part','Part payment']],{l:'How much?',v:'full'})}${F('rpa','full')==='part'?inp('rpAmt',{l:'Amount',pre:'₹',im:'numeric',req:true,pat:'[0-9]{4,6}',msg:'Minimum ₹1,000',h:'Minimum ₹1,000. The rest stays due.'}):''}
 ${lbl('UPI')}${list([opt('gpay','<b style="font-size:12px">G</b>','Google Pay',''),opt('phonepe','<b style="font-size:12px;color:#5F259F">Pe</b>','PhonePe',''),opt('paytm','<b style="font-size:11px;color:#00B9F1">Pay</b>','Paytm',''),opt('upiid',ic('rupee'),'Enter UPI ID','name@bank')])}
 ${F('rpm','gpay')==='upiid'?inp('rpUpi',{l:'Your UPI ID',ph:'rohan@okhdfcbank',req:true,pat:'[a-zA-Z0-9.\\-_]{2,}@[a-zA-Z]{2,}',msg:'Enter a valid UPI ID like name@bank'}):''}
 ${lbl('Other')}${list([opt('card',ic('card'),'Debit / credit card','2% fee'),opt('nb',ic('bank'),'Net banking','')])}
 ${banner('info','cash','Paying cash? Hand it to Ramesh Parmar at the office. Your receipt will appear here once recorded.')}<div class="help" style="text-align:center">${ic('lock','sm')} Secured by Razorpay</div>`,foot:btn('Continue',{act:'rpGo'})})}});
A.rpGo=()=>{const ids=[];if(F('rpa','full')==='part')ids.push('rpAmt');if(F('rpm','gpay')==='upiid')ids.push('rpUpi');if(ids.length&&!validate(ids))return;if(F('rpa','full')==='part'&&+F('rpAmt')>myInv().total){ST.err.rpAmt='Can’t be more than the amount due';render();return}go('rUpi')};

def('rUpi',{t:'UPI payment',m:RR,r:'res',tab:'rRent',code:'Y-04',d:'Hands off to the UPI app for approval. In this prototype, choose whether the payment succeeds or fails to see both outcomes.',try:['Tap “Approve in app” for success, or “Simulate failure”.'],
 v:()=>{const i=myInv(),amt=F('rpa','full')==='part'?+F('rpAmt'):i.total-i.paid,app={gpay:'Google Pay',phonepe:'PhonePe',paytm:'Paytm',upiid:'your UPI app',card:'card page',nb:'your bank'}[F('rpm','gpay')];
 return page({title:'Complete payment',noMode:true,body:`<div class="empty" style="padding-top:30px"><div class="big" style="background:var(--blue-50);color:var(--blue)">${ic('phone','xl')}</div><div class="t-l w7">Approve ${inr(amt)} in ${app}</div><div class="mut">Paying <b>Deven PG Group</b> (devenpg@hdfcbank via Razorpay). Request expires in <b>4:52</b>.</div></div>
 ${card(kv([['Amount',inr(amt)],['For',i.month+' rent'],['Order ID','order_NpD7'+DB.me.toUpperCase()]]))}${banner('warn','alert','Don’t press back or close the app until the payment is confirmed.')}`,foot:btn('Simulate failure',{k:'s',act:'rpFail'})+btn('Approve in app',{act:'rpOk',p:{amt}})})}});
A.rpOk=p=>{rep('rProc',{amt:p.amt,ok:1})};A.rpFail=()=>rep('rProc',{ok:0});
def('rProc',{t:'Payment processing',m:RR,r:'res',tab:'rRent',code:'Y-05',hide:true,d:'Waiting for confirmation from the payment gateway (usually 2–5 seconds).',
 v:()=>page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:160px"><div class="skel" style="width:80px;height:80px;border-radius:50%"></div><div class="t-l w7">Processing payment…</div><div class="mut">Confirming with your bank. This usually takes a few seconds.</div></div>`}),
 after:p=>{clearTimeout(window._rp);window._rp=setTimeout(()=>{if(cur().id!=='rProc')return;if(String(p.ok)==='1'){const i=myInv(),amt=+p.amt,id='PAY-'+(9500+DB.pay.length);DB.pay.push({id,invId:i.id,resId:DB.me,propId:'p1',amt,method:'UPI',app:{gpay:'Google Pay',phonepe:'PhonePe',paytm:'Paytm'}[F('rpm','gpay')]||'UPI',ref:'UTR 6'+Math.floor(1e10+Math.random()*9e10),date:TODAY,time:'2:24 PM',status:'Success'});i.paid=Math.min(i.total,i.paid+amt);i.status=i.paid>=i.total?'Paid':'Partial';DB.notifs.unshift({id:'O'+Date.now(),type:'pay',title:'Payment received',text:`${inr(amt)} by UPI from Rohan Sharma · A-201`,time:'Just now',read:false,go:'payDetail',p:{id}});rep('rPaySuccess',{id})}else rep('rPayFail',{})},1600)}});
def('rPaySuccess',{t:'Payment success',m:RR,r:'res',tab:'rRent',code:'Y-06',hide:true,d:'Success state. The receipt is generated instantly and the owner’s dashboard updates in real time (switch to the Owner app to see the new payment and notification).',try:['Switch to “Owner app” on the left: the payment shows in Notifications and Finance.'],
 v:p=>{const x=DB.pay.find(y=>y.id===p.id);return page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:60px"><div class="big" style="background:var(--green-50);color:var(--green);border-radius:50%">${ic('check','xl')}</div><div class="t-xl w7">Payment successful</div><div class="t-xxl w7 num">${inr(x.amt)}</div><div class="mut">Paid to Sunrise Boys PG · ${x.app}</div></div>${card(kv([['Transaction ID',x.ref.replace('UTR ','')],['Date',`${x.date}, ${x.time}`],['Receipt no.','RCP-'+x.id.replace('PAY-','')]]))}${btn('View receipt',{icon:'receipt',act:'rpRcpt',p:{id:x.id}})}${btn('Back to home',{k:'s',tab:'rHome'})}`})}});
A.rpRcpt=p=>rep('rReceipt',{id:p.id});
def('rPayFail',{t:'Payment failed',m:RR,r:'res',tab:'rRent',code:'Y-07',d:'Failure state with the likely reason and what happens to the money if it was debited.',
 v:()=>page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:60px"><div class="big" style="background:var(--red-50);color:var(--red);border-radius:50%">${ic('x','xl')}</div><div class="t-xl w7">Payment failed</div><div class="mut">Your bank declined the request or it timed out. No money was taken.</div></div>${banner('info','help','If money was debited, it is refunded automatically to your account within 5–7 working days.')}${btn('Try again',{icon:'refresh',act:'rpRetry'})}${btn('Choose another method',{k:'s',act:'rpRetry'})}${btn('Need help?',{k:'g',go:'rHelp'})}`})});
A.rpRetry=()=>rep('rPayMethod');

def('rReceipt',{t:'Receipt',m:RR,r:'res',tab:'rRent',code:'Y-08',d:'Same receipt document the owner sees. Download as PDF or share.',
 v:p=>{let x=p.id?DB.pay.find(y=>y.id===p.id):null;if(!x){const h=DB.hist.find(y=>y.id===p.h)||DB.hist[0];x={id:h.pay,resId:DB.me,amt:h.total,method:h.method,ref:'UTR 5'+h.id.replace(/\D/g,'')+'07741',date:h.paidOn,month:h.month,invId:null}}
 return page({title:'Receipt',sub:'RCP-'+x.id.replace('PAY-',''),body:receiptDoc(x),foot:btn('Download',{k:'s',icon:'download',act:'toast',p:{m:'Receipt saved to Downloads'}})+btn('Share',{k:'wa',icon:'whats',act:'toast',p:{m:'Receipt shared'}})})}});
def('rHistory',{t:'Payment history',m:RR,r:'res',tab:'rRent',code:'Y-09',d:'All past payments with receipts.',v:()=>{ST.ui.rrt='hist';return S.rRent.v({})}});

// ---------- COMPLAINTS ----------
def('rComplaints',{t:'My complaints',m:RC,r:'res',tab:'rComplaints',code:'Q-01',d:'Every complaint the resident raised with its live status. Raising a new one takes three short steps.',try:['Tap “Raise complaint”.','Open “Wi-Fi very slow” to track it.'],
 empty:{icon:'wrench',title:'No complaints',msg:'Something not working? Raise a complaint and track it here.',cta:'Raise complaint',go:'rCompNew'},
 v:()=>{const cs=myC(),f=U('rcf','open'),sh=cs.filter(c=>f==='all'||(f==='open'?!['Resolved','Closed'].includes(c.status):['Resolved','Closed'].includes(c.status)));
 return page({fab:['Raise complaint',{go:'rCompNew'}],body:`${seg('rcf',[['open','Open'],['done','Resolved'],['all','All']],'open')}
 ${sh.length?list(sh.map(c=>li({icon:ccI(c.cat),bg:'var(--amber-50)',fg:'var(--amber)',title:c.title,sub:`${c.id} · ${c.created}`,sub2:c.assignee?'Assigned to '+ST_(c.assignee).name.split(' ')[0]:'Waiting to be assigned',right:sb(c.status),go:'rCompDetail',p:{id:c.id}}))):emptyB({icon:'check',bg:'var(--green-50)',fg:'var(--green)',title:f==='open'?'No open complaints':'Nothing here',msg:'Everything’s working fine.'})}`})}});

def('rCompNew',{t:'Raise complaint',m:RC,r:'res',tab:'rComplaints',code:'Q-02',d:'Three steps: pick a category → describe the problem and where → add photos and submit. The owner/manager is notified immediately and can assign staff.',try:['Submit without a description to see validation.','Finish and then switch to the Owner app — the complaint is in Complaints with a “New” badge.'],
 v:p=>{const s=+U(K('rcs'),0);if(p.cat&&!F('rcCat'))ST.f.rcCat=p.cat;let body='';
 if(s===0) body=`<div class="t-l w7">What’s the problem?</div>${ST.err.rcCat?`<div class="help err">${ic('alert','sm')}${ST.err.rcCat}</div>`:''}<div class="g3" id="rcCat" data-req data-msg="Choose a category">${CCAT.map(([c,i])=>`<div class="card" data-act="pick" data-p="id:rcCat,v:${c}" role="button" tabindex="0" style="display:grid;justify-items:center;gap:6px;padding:14px 4px;text-align:center;${F('rcCat')===c?'border-color:var(--blue);box-shadow:0 0 0 3px var(--blue-50)':''}"><span class="tile" style="background:var(--blue-50);color:var(--blue)">${ic(i)}</span><span class="t-s w6">${c==='AC'?'AC':c}</span></div>`).join('')}</div>`;
 if(s===1) body=`${bdg(F('rcCat','Other'),'info')}${inp('rcT',{l:'Short title',ph:F('rcCat')==='Wi-Fi'?'Wi-Fi not working on 2nd floor':'e.g. Fan making noise',req:true,msg:'Add a short title'})}${ta('rcD',{l:'Describe the problem',ph:'What happened, since when…',req:true,min:10,msg:'Please describe the problem'})}
  ${pick('rcW',['My room (A-201)','Bathroom','Common area','Kitchen / mess','Other'],{l:'Where?',v:'My room (A-201)'})}${pick('rcU',['Normal','Urgent'],{l:'How urgent?',v:'Normal',h:'Urgent = safety issue, no water, no power'})}
  ${pick('rcTm',['Anytime','Morning','Evening (after 6 PM)'],{l:'Best time for staff to visit',v:'Evening (after 6 PM)'})}`;
 if(s===2) body=`<div class="t-l w7">Add photos (optional)</div><div class="t-s mut">Photos help staff bring the right tools.</div><div class="g3">${['rcP1','rcP2','rcP3'].map((k,i)=>`<div class="upl ${F(k)?'done':''}" data-act="upl" data-p="id:${k},n:photo_${i+1}.jpg" role="button" tabindex="0" style="aspect-ratio:1;padding:6px">${ic(F(k)?'check':'cam','lg')}<span class="t-xs">${F(k)?'Added':'Add'}</span></div>`).join('')}</div>
  ${card(kv([['Category',F('rcCat','Other')],['Title',esc(F('rcT',''))],['Where',F('rcW','My room (A-201)')],['Urgency',F('rcU','Normal')]]))}`;
 return page({title:'Raise complaint',sub:`Step ${s+1} of 3`,close:true,body:`${steps(3,s)}${body}`,foot:(s>0?btn('Back',{k:'s',act:'ui',p:{k:K('rcs'),v:s-1}}):'')+btn(s<2?'Next':'Submit complaint',{act:'rcNext',p:{s}})})}});
A.rcNext=p=>{const s=+p.s;if(s===0&&!validate(['rcCat']))return;if(s===1&&!validate(['rcT','rcD']))return;if(s<2){ST.ui[K('rcs')]=s+1;render(true);return}
 const id='CMP-'+(1200+DB.comp.length);DB.comp.unshift({id,propId:'p1',room:'A-201',resId:DB.me,cat:F('rcCat'),title:F('rcT'),desc:F('rcD'),status:'New',pri:F('rcU','Normal')==='Urgent'?'High':'Medium',created:TODAY+' · 2:30 PM',assignee:null,notes:[],photos:['rcP1','rcP2','rcP3'].filter(k=>F(k)).length,rating:null});
 DB.notifs.unshift({id:'O'+Date.now(),type:'comp',title:'New complaint · '+F('rcT'),text:'Sunrise · A-201 · Rohan Sharma',time:'Just now',read:false,go:'compDetail',p:{id}});
 clearF('rc');delete ST.ui[K('rcs')];rep('rCompDone',{id})};
def('rCompDone',{t:'Complaint submitted',m:RC,r:'res',tab:'rComplaints',code:'Q-03',hide:true,d:'Success state.',v:p=>page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:70px"><div class="big" style="background:var(--green-50);color:var(--green);border-radius:50%">${ic('check','xl')}</div><div class="t-xl w7">Complaint submitted</div><div class="mut">Ticket <b>${p.id}</b>. The PG manager has been notified. You’ll get an update when someone is assigned.</div></div>${btn('Track complaint',{act:'rcTrack',p:{id:p.id}})}${btn('Back to complaints',{k:'s',tab:'rComplaints'})}`})});
A.rcTrack=p=>rep('rCompDetail',{id:p.id});

def('rCompDetail',{t:'Track complaint',m:RC,r:'res',tab:'rComplaints',code:'Q-04',dp:{id:'CMP-1187'},d:'Live status tracker, who is assigned and when they’ll come, updates from staff, resolution details and — once resolved — a rating and feedback form. Internal staff notes are never shown here.',try:['Open a resolved/closed complaint to see the feedback.','On a resolved complaint, rate it and submit — it closes.'],
 v:p=>{const c=DB.comp.find(x=>x.id===p.id)||myC()[0],si=CSTAT.indexOf(c.status),s=c.assignee?ST_(c.assignee):null,rt=+F('fb_'+c.id,0);
 return page({title:c.title,sub:c.id,body:`${card(stepper(['Submitted','Assigned','Working','Resolved','Closed'],si))}
 ${c.status==='Resolved'?banner('ok','check','Your complaint has been resolved. Please confirm and rate the service.'):''}
 ${s?card(`${lbl('Assigned to')}<div class="row" style="margin-top:8px"><div class="av">${initials(s.name)}</div><div style="flex:1"><div class="w7">${s.name}</div><div class="t-s mut">${s.role}${c.status==='In Progress'?' · visiting 3 Dec, 11 AM':''}</div></div>${btn('Call',{k:'s',sm:true,act:'toast',p:{m:'Calling '+s.mobile}})}</div>`):card('<div class="t-s mut">Waiting for the manager to assign someone. Usually within 2 hours.</div>')}
 ${card(`<div class="chips">${bdg(c.cat,'mute')}${sb(c.pri)}</div><div class="t-m" style="margin-top:8px">${c.desc}</div>${c.photos?`<div class="g3" style="margin-top:10px">${Array.from({length:c.photos}).map(()=>`<div class="ph">${ic('img','lg')}</div>`).join('')}</div>`:''}`)}
 ${c.resolution?sec('Resolution')+card(kv([['What was done',c.resolution],['Resolved on',c.resolvedOn]])):''}
 ${sec('Updates')}${card(tl([['Submitted',c.created,'ok'],...(s?[['Assigned to '+s.name.split(' ')[0],'Manager assigned the task','ok']]:[]),...(c.status==='In Progress'?[['Technician visit booked','3 Dec, 11 AM','on']]:[]),...(si>=3?[['Resolved',c.resolvedOn||'','ok']]:[])]))}
 ${c.status==='Resolved'&&!c.rating?`${sec('Rate the service')}${card(`<div class="stars">${[1,2,3,4,5].map(i=>`<svg viewBox="0 0 24 24" class="${i<=rt?'f':''}" data-act="pick" data-p="id:fb_${c.id},v:${i}" role="button" aria-label="${i} stars"><use href="#i-star"/></svg>`).join('')}</div>${ta('fbt_'+c.id,{ph:'Anything to add? (optional)'})}${btn('Submit feedback & close',{act:'rFb',p:{id:c.id}})}${btn('Not fixed — reopen',{k:'g',act:'rReopen',p:{id:c.id}})}`)}`:''}
 ${c.rating?sec('Your feedback')+card(`<div class="stars">${[1,2,3,4,5].map(i=>`<svg viewBox="0 0 24 24" class="${i<=c.rating?'f':''}" style="width:22px;height:22px"><use href="#i-star"/></svg>`).join('')}</div><div class="t-s mut" style="margin-top:4px">${c.feedback||''}</div>`):''}`})}});
A.rFb=p=>{const c=DB.comp.find(x=>x.id===p.id),r=+F('fb_'+c.id,0);if(!r){toast('Tap the stars to rate','err');return}c.rating=r;c.feedback=F('fbt_'+c.id,'');c.status='Closed';render();toast('Thanks for your feedback!')};
A.rReopen=p=>{DB.comp.find(x=>x.id===p.id).status='In Progress';render();toast('Complaint reopened · manager notified')};

// ---------- NOTICES ----------
def('rNotices',{t:'Notices',m:RN,r:'res',tab:'rNotices',code:'W-01',d:'PG notice board: announcements, maintenance notices, important alerts and rules. Unread notices are marked; opening one marks it read.',try:['Tap the Unread chip.','Open the water-supply notice.'],
 empty:{icon:'mega',title:'No notices yet',msg:'Announcements from your PG will appear here.'},
 v:()=>{const f=U('rnf','all'),ns=myN().filter(n=>f==='all'||(f==='unread'?!n.read:n.type===f));
 return page({right:`<button class="ib" data-act="rReadAll" aria-label="Mark all read">${ic('check')}</button>`,body:`${chips('rnf',[['all','All'],['unread','Unread',myN().filter(n=>!n.read).length],['Announcement','Announcements'],['Maintenance','Maintenance'],['Important','Important'],['Rule','Rules']],'all',{scroll:true})}
 ${card(`<div class="row"><div class="tile" style="background:var(--blue-50);color:var(--blue)">${ic('file')}</div><div style="flex:1"><div class="w7">PG rules & policies</div><div class="t-s mut">Curfew ${PR('p1').curfew} · visitor hours · notice period</div></div>${ic('right','sm mut2')}</div>`,'',{go:'rRules'})}
 ${ns.length?list(ns.map(n=>li({icon:{Maintenance:'wrench',Important:'alert',Rule:'file',Announcement:'mega'}[n.type],bg:n.type==='Important'?'var(--red-50)':'var(--blue-50)',fg:n.type==='Important'?'var(--red)':'var(--blue)',title:`${n.read?'':'<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--blue);margin-right:6px;vertical-align:middle"></span>'}${n.title}`,sub:`${n.type} · ${n.date}`,go:'rNoticeDetail',p:{id:n.id},style:n.read?'':'background:#FAFCFF'}))):emptyB({icon:'check',bg:'var(--green-50)',fg:'var(--green)',title:'You’re all caught up',msg:'No notices in this filter.'})}`})}});
A.rReadAll=()=>{myN().forEach(n=>n.read=true);render();toast('All notices marked as read')};
def('rNoticeDetail',{t:'Notice details',m:RN,r:'res',tab:'rNotices',code:'W-02',dp:{id:'N1'},d:'Full notice text with date and who sent it.',
 v:p=>{const n=DB.notices.find(x=>x.id===p.id);n.read=true;return page({title:n.type,body:`${sb(n.type==='Important'?'High':n.type==='Maintenance'?'Medium':'Low').replace(/High|Medium|Low/,n.type)}<div class="t-xl w7">${n.title}</div><div class="t-s mut">${n.date} · from Sunrise Boys PG management</div>${card(`<div class="t-m" style="line-height:1.6">${n.body}</div>`)}${n.type==='Maintenance'?btn('Add to calendar',{k:'s',icon:'cal',act:'toast',p:{m:'Added to your calendar'}}):''}`})}});
def('rRules',{t:'PG rules & policies',m:RN,r:'res',tab:'rNotices',code:'W-03',d:'House rules set by the owner for this property: timings, visitors, conduct, notice period and deposit refund policy.',
 v:()=>{const P=PR('p1');return page({title:'PG rules',sub:P.name,body:[['clock','Timings',[`Gate closes at ${P.curfew}. Late entry needs prior approval from the warden.`,'Quiet hours 10:30 PM – 7:00 AM.','Mess timings: breakfast 7:30–9:30, lunch 12:30–2:30, dinner 8:00–10:00.']],['door','Visitors',['Visitors allowed 9 AM – 8 PM, common area only.','No overnight guests.','All visitors sign in at the security desk with photo ID.']],['shield','Conduct',['Smoking, alcohol and drugs are strictly prohibited.','Cooking is not allowed in rooms.','Switch off AC, lights and geyser when leaving.']],['rupee','Rent & deposit',['Rent is due on the 5th; ₹500 late fee after 5 days.','30-day notice before leaving.','Deposit refunded within 7 days of check-out, minus any dues or damage.']]].map(([i,t,xs])=>card(`<div class="row" style="margin-bottom:8px"><div class="tile" style="width:32px;height:32px;background:var(--blue-50);color:var(--blue)">${ic(i,'sm')}</div><b>${t}</b></div><ul style="margin:0;padding-left:18px;display:grid;gap:5px" class="t-s">${xs.map(x=>`<li>${x}</li>`).join('')}</ul>`)).join('')+`<div class="help">Last updated 20 Nov 2026</div>`})}});

