def('rProfile',{t:'My profile',m:RP,r:'res',tab:'rProfile',code:'Z-01',d:'Resident’s own details and documents: personal info, guardian and emergency contacts, KYC, PG details, deposit, stay history, check-out request, visitors, settings and help.',try:['Open KYC documents.','Open Security deposit.','Tap “Request check-out”.'],
 v:()=>{const me=ME();return page({body:`${card(`<div class="row"><div class="av" style="width:58px;height:58px;font-size:18px">RS</div><div style="flex:1"><div class="t-l w7">${me.name}</div><div class="t-s mut">${me.mobile}</div><div class="chips" style="margin-top:5px">${sb(me.status)}${bdg('KYC verified','ok')}</div></div></div>`,'',{go:'rEdit'})}
 ${list([li({icon:'user',title:'Personal details',go:'rEdit'}),li({icon:'users',title:'Guardian & emergency contact',sub:me.guardian.name+' · '+me.guardian.rel,go:'rGuardian'}),li({icon:'badge',title:'KYC documents',sub:'Verified',go:'rKyc'})])}
 ${list([li({icon:'home',title:'My PG & room',sub:'Sunrise Boys PG · A-201 Bed B',go:'rRoom'}),li({icon:'shield',title:'Security deposit',sub:inr(me.deposit)+' held',go:'rDeposit'}),li({icon:'clock',title:'Stay history',sub:'Since '+me.join,go:'rStay'}),li({icon:'out',title:me.status==='Notice'?'Check-out scheduled':'Request check-out',sub:me.status==='Notice'?'Leaving '+me.checkout:'30-day notice',go:'rCheckout'}),li({icon:'door',title:'My visitors',go:'rVisitors'})])}
 ${list([li({icon:'gear',title:'Settings',sub:'Language, notifications',go:'rSettings'}),li({icon:'help',title:'Help & support',go:'rHelp'}),li({icon:'logout',bg:'var(--red-50)',fg:'var(--red)',title:'<span class="c-err">Log out</span>',act:'askLogout'})])}`})}});
def('rEdit',{t:'Edit personal details',m:RP,r:'res',tab:'rProfile',code:'Z-02',d:'Residents can update contact details. Name, mobile and date of birth are locked because they’re tied to KYC — changes go through the PG manager.',try:['Change the email to something invalid and save.'],
 v:()=>{const me=ME();return page({title:'Personal details',body:`<div class="row"><div class="av" style="width:64px;height:64px;font-size:20px">RS</div>${btn('Change photo',{k:'s',sm:true,act:'toast',p:{m:'Photo picker'}})}</div>${inp('re_n',{l:'Full name',v:me.name,ro:true,h:'Locked after KYC. Ask your PG manager to change it.'})}${inp('re_m',{l:'Mobile',pre:'+91',v:me.mobile.replace('+91 ',''),ro:true})}${inp('re_e',{l:'Email',v:me.email,type:'email',pat:'[^@]+@[^@]+\\.[a-z]{2,}',msg:'Enter a valid email'})}${inp('re_d',{l:'Date of birth',v:me.dob,ro:true})}${pick('re_o',['Student','Working professional'],{l:'Occupation',v:me.occ})}${inp('re_c',{l:'College / company',v:me.org})}${ta('re_a',{l:'Permanent address',v:me.addr})}`,foot:btn('Save changes',{act:'reSave'})})}});
A.reSave=()=>{if(!validate(['re_e']))return;const me=ME();me.email=F('re_e',me.email);me.org=F('re_c',me.org);back();toast('Details updated')};
def('rGuardian',{t:'Guardian & emergency',m:RP,r:'res',tab:'rProfile',code:'Z-03',d:'Guardian and emergency contacts the PG will call if something happens.',
 v:()=>{const me=ME();return page({title:'Guardian & emergency',body:`${lbl('Guardian')}${inp('rg_n',{l:'Name',v:me.guardian.name,req:true})}${pick('rg_r',['Father','Mother','Brother','Sister','Uncle','Spouse','Other'],{l:'Relation',v:me.guardian.rel})}${inp('rg_m',{l:'Mobile',pre:'+91',v:me.guardian.mobile.replace('+91 ','').replace(' ',''),req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}${lbl('Emergency contact')}${inp('re2_n',{l:'Name',v:me.emergency.name})}${inp('re2_m',{l:'Mobile',pre:'+91',v:me.emergency.mobile.replace('+91 ','').replace(' ',''),pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}`,foot:btn('Save',{act:'rgSave'})})}});
A.rgSave=()=>{if(!validate(['rg_n','rg_m','re2_m']))return;back();toast('Contacts updated · PG manager notified')};
def('rKyc',{t:'KYC documents',m:RP,r:'res',tab:'rProfile',code:'Z-04',d:'Verification status and uploaded documents. Residents can verify with DigiLocker (Aadhaar never stored in full) or upload another ID. Expiring documents trigger reminders.',try:['Tap “Upload another document”.'],
 v:()=>page({title:'KYC documents',body:`${card(`<div class="row"><div class="tile" style="background:var(--green-50);color:var(--green)">${ic('shield')}</div><div style="flex:1"><div class="w7">KYC verified</div><div class="t-s mut">Aadhaar via DigiLocker · XXXX XXXX 4821</div></div>${sb('Verified')}</div>`)}
 ${card(`<div class="between"><b>Police verification</b>${sb('Verified')}</div><div class="t-s mut" style="margin-top:4px">Submitted by Sunrise Boys PG on 3 Jul 2025</div>`)}
 ${sec('Documents')}${list([li({icon:'file',title:'Aadhaar (DigiLocker)',sub:'Name, DOB, photo, last 4 digits only',right:sb('Verified'),chev:false}),li({icon:'file',title:'Office ID · L&T Technology Services',sub:'Expires 30 Jun 2027',right:sb('Verified'),chev:false}),li({icon:'img',title:'Passport photo',right:sb('Verified'),chev:false})])}
 ${sec('Add document')}${pick('rk_t',['PAN card','Passport','Driving licence','College / office ID'],{v:'PAN card'})}<div class="g2">${upl('rk_f','Front','pan_front.jpg')}${upl('rk_b','Back (if any)','pan_back.jpg')}</div><div class="row t-s" style="align-items:flex-start">${cbx('rk_ok',false)}<span class="mut">I consent to Sunrise Boys PG storing this document for identity verification as required by law.</span></div>`,foot:btn('Upload document',{act:'rkSave'})})});
A.rkSave=()=>{if(!F('rk_f')){toast('Add the front side photo','err');return}if(!F('rk_ok',false)){toast('Please give consent to upload','err');return}clearF('rk_');render();toast('Document uploaded · waiting for PG review')};
def('rDeposit',{t:'Security deposit',m:RP,r:'res',tab:'rProfile',code:'Z-05',d:'How much deposit the PG holds, when it was paid, the refund policy and an estimate of the refund if the resident leaves now.',
 v:()=>{const me=ME();return page({title:'Security deposit',body:`${card(`${lbl('Deposit held')}<div class="t-xxl w7 num">${inr(me.deposit)}</div><div class="t-s mut">Paid on ${me.join} · UPI · RCP-6610</div>`)}${sec('If you leave after notice')}${card(kv([['Deposit',inr(me.deposit)],['Pending rent',inr(0)],['Damages','None recorded'],['Estimated refund',`<span class="t-l c-ok">${inr(me.deposit)}</span>`]]))}${banner('info','clock','Refunded within 7 days of check-out to your UPI or bank account.')}${sec('Transactions')}${list([li({icon:'in',bg:'var(--green-50)',fg:'var(--green)',title:'Deposit paid',sub:me.join+' · UPI',right:`<b class="num c-ok">${inr(me.deposit)}</b>`,chev:false})])}`})}});
def('rStay',{t:'Stay history',m:RP,r:'res',tab:'rProfile',code:'Z-06',d:'Timeline of the resident’s stay: check-in, room changes, notices.',
 v:()=>page({title:'Stay history',body:card(tl([['Checked in · Sunrise Boys PG','1 Jul 2025 · B-103 Bed A','ok'],['Moved to A-201 Bed B','1 Feb 2026 · AC room upgrade','ok'],['KYC & police verification done','3 Jul 2025','ok'],['Currently staying','17 months','on']]))+sec('Previous PGs')+list([li({icon:'bldg',title:'Krishna PG (another business)',sub:'Not visible — stays at other businesses are private',chev:false})])})});
def('rCheckout',{t:'Check-out request',m:RP,r:'res',tab:'rProfile',code:'Z-07',d:'Resident gives notice from the app. The earliest date respects the 30-day notice period; the owner gets the request and starts the settlement at check-out.',try:['Pick a date earlier than 1 Jan 2027 to see the notice-period error.'],
 v:()=>{const me=ME();if(me.status==='Notice')return page({title:'Check-out',body:`${banner('warn','clock',`Your check-out is scheduled for <b>${me.checkout}</b>.`)}${card(kv([['Notice given',TODAY],['Last day',me.checkout],['Estimated refund',inr(me.deposit)]]))}${sec('Before you leave')}${list(['Return room keys and ID card','Clear cupboard and room','Pay any pending dues','Final meter reading by warden'].map(x=>li({lead:cbx('ck_'+x.length,false),title:x,chev:false})))}${btn('Withdraw notice',{k:'s',act:'rCoWithdraw'})}`});
 return page({title:'Request check-out',body:`${banner('info','clock','Notice period is 30 days. Earliest check-out date: <b>1 Jan 2027</b>.')}${inp('rco_d',{l:'Check-out date',type:'date',v:'2027-01-01',req:true})}${pick('rco_r',['Course completed','Job change','Moving to own flat','Not satisfied','Other'],{l:'Reason',req:true})}${ta('rco_n',{l:'Anything we should know? (optional)'})}${inp('rco_u',{l:'UPI ID for deposit refund',v:'rohan.sharma@okhdfcbank',req:true,pat:'[a-zA-Z0-9.\\-_]{2,}@[a-zA-Z]{2,}',msg:'Enter a valid UPI ID'})}`,foot:btn('Submit request',{act:'rCoSave'})})}});
A.rCoSave=()=>{if(!validate(['rco_d','rco_r','rco_u']))return;const d=new Date(F('rco_d','2027-01-01'));if(d<new Date(2027,0,1)){ST.err.rco_d='Must be on or after 1 Jan 2027 (30-day notice)';render();toast('Check the date','err');return}confirmD({icon:'out',title:'Submit check-out request?',msg:`Your last day will be ${fdate(F('rco_d','2027-01-01'))}. The PG manager will confirm and settle your deposit.`,ok:'Submit',act:'rCoDo'})};
A.rCoDo=()=>{const me=ME();me.status='Notice';me.checkout=fdate(F('rco_d','2027-01-01'));clearF('rco_');closeOv();render();toast('Request sent to Sunrise Boys PG')};
A.rCoWithdraw=()=>{const me=ME();me.status='Active';delete me.checkout;render();toast('Notice withdrawn')};
def('rVisitors',{t:'My visitors',m:RP,r:'res',tab:'rProfile',code:'Z-08',d:'Residents pre-register a visitor so the gate already has their details; they also see who visited them.',try:['Pre-register a visitor.'],
 v:()=>page({title:'My visitors',body:`${banner('info','clock','Visitors allowed 9 AM – 8 PM in the common area. No overnight guests.')}${sec('Pre-register a visitor')}${inp('rv_n',{l:'Visitor name',req:true,msg:'Enter the visitor’s name'})}${inp('rv_m',{l:'Mobile',pre:'+91',im:'numeric',max:10,req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid mobile number'})}<div class="g2">${pick('rv_r',['Parent','Relative','Friend'],{l:'Relation',v:'Parent'})}${inp('rv_d',{l:'Date',type:'date',v:'2026-12-07'})}</div>${btn('Pre-register',{act:'rvSave'})}${sec('Past visits')}${list(DB.visitors.filter(v=>v.resId===DB.me).map(v=>li({av:initials(v.name),title:v.name,sub:`${v.rel} · in ${v.in}${v.out?' · out '+v.out:' · inside now'}`,chev:false})))}`})});
A.rvSave=()=>{if(!validate(['rv_n','rv_m']))return;clearF('rv_');render();toast('Visitor pre-registered · security desk informed')};
def('rSettings',{t:'Settings',m:RP,r:'res',tab:'rProfile',code:'Z-09',d:'Language, notification preferences and app lock for the resident.',
 v:()=>page({title:'Settings',body:`${list([li({icon:'globe',title:'Language',sub:{en:'English',hi:'हिन्दी',gu:'ગુજરાતી'}[F('lang','en')],act:'sheet',p:{s:'lang'}})])}${lbl('Notify me about')}${list([togRow('rn1','Rent reminders','Push + WhatsApp',true,'rupee'),togRow('rn2','Complaint updates','Push',true,'wrench'),togRow('rn3','PG notices','Push',true,'mega'),togRow('rn4','Visitor arrivals','Push',true,'door')])}${list([togRow('rn5','App lock','Fingerprint to open',false,'finger')])}`})});
def('rHelp',{t:'Help & contact PG',m:RP,r:'res',tab:'rProfile',code:'Z-10',d:'How to reach the PG and common questions.',
 v:()=>page({title:'Help',body:`<div class="g2">${btn('Call manager',{k:'s',icon:'call',act:'toast',p:{m:'Calling Ramesh Parmar'}})}${btn('WhatsApp PG',{k:'wa',icon:'whats',act:'toast',p:{m:'Opening WhatsApp'}})}</div>${sec('Common questions')}${list([['When is rent due?','On the 5th of every month. Late fee ₹500 after 5 days.'],['I paid in cash — where is my receipt?','It appears in Rent → History once the manager records it.'],['Payment debited but failed?','It is refunded automatically in 5–7 working days.'],['How do I change my room?','Ask the manager; room changes are done by the PG.']].map(([q,a])=>li({title:q,sub:a,chev:false})))}${btn('Report an app problem',{k:'g',act:'toast',p:{m:'Problem report sent to PG ERP support'}})}`})});
